WITH filtered_suppliers AS (SELECT *, COALESCE(city, 'N/A') AS city_filled FROM suppliers WHERE rating >= 2.4 AND supplier_name LIKE '%Lion%' AND city = 'Bangkok'), summary AS (SELECT country, CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, SORT_ARRAY(COLLECT_SET(city)) AS city_list FROM filtered_suppliers GROUP BY country, CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END) SELECT country, rating_bucket, city_list FROM summary ORDER BY rating_bucket, country;
